function statusBadge(key){const [label, cls]=statuses[key]||statuses.unknown; return `<span class="health-badge ${cls}"><span class="status-dot ${cls}"></span>${label}</span>`}
function renderNav(){nav.innerHTML=navGroups.map(group=>`<div class="nav-divider"></div><div class="section-label" style="padding:6px 11px;color:#759087">${group.label}</div>${group.items.map(([id,label,icon])=>`<button class="nav-item ${currentView===id?'active':''}" data-view="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('')}`).join(''); nav.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));}
