function card(title,body,extra=''){return `<section class="card"><div class="panel-heading"><h3>${title}</h3>${extra}</div>${body}</section>`}
function chatView(){return `${heading('SECRETARY / CHAT','Chat','Persistent conversations shared with Discord and CLI.','<button class="primary-button" data-action="new-chat">New Chat +</button>')}<div class="chat-layout chat-history-layout"><aside class="card chat-history"><div class="chat-history-head"><strong>Conversations</strong><button class="quiet-button" data-action="toggle-archived">Archived</button></div><input id="session-search" class="select-control" placeholder="Search conversations" aria-label="Search conversations"><div id="session-list" class="session-list"><div class="stat-card">Loading conversations...</div></div></aside><section class="card chat-panel"><div class="chat-header"><div><span class="eyebrow">CONVERSATION</span><h2 id="chat-session-title">New chat</h2><div id="chat-session-source" class="subtext">WebUI · not saved until the first message</div></div><div class="chat-header-actions"><button class="quiet-button" data-action="rename-session" disabled>Rename</button><button class="quiet-button" data-action="archive-session" disabled>Archive</button></div></div><div class="chat-messages"><div class="stat-card" style="margin:auto;text-align:center;color:var(--muted)">No conversation yet. Start a new chat or send a message.</div></div><div class="response-meta"><span class="meta-pill"><strong>Model</strong> —</span><span class="meta-pill"><strong>Provider</strong> —</span><span class="meta-pill"><strong>Execution</strong> —</span><span class="meta-pill"><strong>Tokens</strong> —</span><span class="meta-pill"><strong>Latency</strong> —</span><span class="meta-pill"><strong>Local/cloud</strong> —</span><button class="details-toggle" data-action="toggle-details">Details</button></div><pre id="execution-details" class="execution-details">No execution details.</pre><div class="composer"><textarea placeholder="Ask your secretary anything..." aria-label="Message"></textarea><button class="send-button" data-action="send-message" aria-label="Send message">Send</button></div></section></div>`}
