function settingsView(){return `${heading('SYSTEM / PREFERENCES','Settings','Communication is backed by the shared VirtizAI preference store. Changes apply to this WebUI identity and persist across reloads.','<button class="primary-button" data-action="save-settings">Save changes <span>✓</span></button>')}<div class="settings-layout"><div class="settings-nav"><button class="active" type="button">Communication</button><button type="button" disabled title="Security settings are not exposed in this slice">Security</button><button type="button" disabled title="Access settings are not exposed in this slice">Access</button><button type="button" disabled title="Update policy is managed by Releases / Updates">Updates</button></div><div class="card form-panel"><div class="form-row"><div class="form-copy"><strong>Response verbosity</strong><small>How much explanation belongs in the final answer.</small></div><div class="segmented" data-setting="response"><button class="segment" data-value="minimal">Minimal</button><button class="segment" data-value="concise">Concise</button><button class="segment" data-value="normal">Normal</button><button class="segment" data-value="detailed">Detailed</button><button class="segment" data-value="expert">Expert</button></div></div><div class="form-row"><div class="form-copy"><strong>Execution updates</strong><small>Operational progress stays separate from conversation context.</small></div><div class="segmented" data-setting="updates"><button class="segment" data-value="silent">Silent</button><button class="segment" data-value="important_milestones">Important milestones</button><button class="segment" data-value="detailed">Detailed</button><button class="segment" data-value="full_trace">Full trace</button></div></div><div class="form-row"><div class="form-copy"><strong>Tool details</strong><small>Choose how commands and results appear in the interface.</small></div><div class="segmented" data-setting="tools"><button class="segment" data-value="hidden">Hidden</button><button class="segment" data-value="summary">Summary</button><button class="segment" data-value="commands_results">Commands/results</button></div></div><div class="form-row"><div class="form-copy"><strong>Secretary route</strong><small>The configured provider:model and residency state remain authoritative in Providers, Models, and Routing.</small></div><div id="secretary-status" class="subtext">Loading live route state...</div></div><div id="settings-status" class="subtext" role="status"></div></div></div>`}
function providerFormView(){return `${heading('REGISTRY / PROVIDERS','Add provider','Connect any compatible provider. For a local Ollama instance, enter the reachable base URL and discover its installed models.')}<section class="card form-panel"><div class="form-row"><div class="form-copy"><strong>Provider name</strong><small>A label for this configured endpoint. It can be anything meaningful to you.</small></div><input id="provider-name" class="select-control" placeholder="My local Ollama"></div><div class="form-row"><div class="form-copy"><strong>Adapter type</strong><small>The first real adapter in this build is Ollama. More adapters will use the same provider contract.</small></div><select id="provider-type" class="select-control"><option value="ollama">Ollama</option></select></div><div class="form-row"><div class="form-copy"><strong>Endpoint</strong><small>Base URL such as http://127.0.0.1:11434. An optional trailing /v1 is accepted and normalized.</small></div><input id="provider-endpoint" class="select-control" placeholder="http://127.0.0.1:11434"></div><div class="wizard-note">No model name is required here. VirtizAI will ask the provider for its installed models. Credentials, when needed, are stored as secret references and never returned to this form.</div><div id="provider-form-status" class="subtext" style="margin-top:16px"></div><div style="display:flex;justify-content:flex-end;gap:10px;margin-top:22px"><button class="quiet-button" data-view="providers">Cancel</button><button class="primary-button" data-action="save-provider">Save and discover models <span>â</span></button></div></section>`}
