function jobsView(){return `${heading('OPERATE / JOBS','Jobs','Asynchronous work remains separate from the conversational model.')}<div id="jobs-list" class="card"><div class="table-row table-head"><div>Job</div><div>Status</div><div>Worker</div><div>Actions</div></div></div>`}
function activityView(){return `${heading('OPERATE / AUDIT','Activity','Execution telemetry and authorization decisions stay out of conversational history.')}<div id="activity-list" class="card"><div class="table-row table-head"><div>Tool</div><div>Driver</div><div>Authorization</div><div>Result</div></div></div>`}
function liveDashboardView(data){const providers=data.providers||{};const jobs=data.jobs||{};const healthy=providers.healthy||0;const providerTotal=Object.values(providers).reduce((sum,value)=>sum+value,0);const jobTotal=Object.values(jobs).reduce((sum,value)=>sum+value,0);const latency=data.secretary_latency_ms==null?'No responses yet':`${Number(data.secretary_latency_ms).toFixed(2)} ms`;const activity=data.recent_activity||[];const p50=data.secretary_latency_p50_ms==null?'â':`${Number(data.secretary_latency_p50_ms).toFixed(2)} ms`;const p95=data.secretary_latency_p95_ms==null?'â':`${Number(data.secretary_latency_p95_ms).toFixed(2)} ms`;return `${heading('OVERVIEW','Dashboard','Live operational state from VirtizAI telemetry, provider health, jobs, and execution audit.')}<div class="grid grid-3" style="margin-bottom:16px"><div class="card stat-card"><span class="metric-label">Secretary latency</span><div class="stat-number">${latency}</div><div class="subtext">p50 ${p50} Â· p95 ${p95} Â· ${data.secretary_response_count||0} responses</div></div><div class="card stat-card"><span class="metric-label">Healthy providers</span><div class="stat-number">${healthy} <small>/ ${providerTotal}</small></div><div class="subtext">Live registry health</div></div><div class="card stat-card"><span class="metric-label">Jobs recorded</span><div class="stat-number">${jobTotal}</div><div class="subtext">Persisted job states</div></div></div>${card('System posture',`<div class="table-row table-head"><div>Component</div><div>Role</div><div>Status</div><div>Measured</div></div><div class="table-row"><div class="service-name"><span class="status-dot healthy"></span><div>Core API<small>SQLite / WAL</small></div></div><div>Application</div><div>${statusBadge('healthy')}</div><div class="subtext">Live</div></div><div class="table-row"><div class="service-name"><span class="status-dot ${data.secretary_response_count?'healthy':'unknown'}"></span><div>Secretary path<small>Persisted assistant latency</small></div></div><div>Routing</div><div>${statusBadge(data.secretary_response_count?'healthy':'unknown')}</div><div class="subtext">${latency}</div></div><div class="table-row"><div class="service-name"><span class="status-dot ${healthy?'healthy':'unknown'}"></span><div>Provider registry<small>${providerTotal} configured</small></div></div><div>Models</div><div>${statusBadge(healthy?'healthy':'unknown')}</div><div class="subtext">Live</div></div>`,'<button class="text-link" data-view="activity">View activity â</button>')}<div class="card" style="margin-top:16px"><div class="panel-heading"><h3>Recent execution activity</h3></div>${activity.length?activity.map(item=>`<div class="table-row"><div>${item.tool_id||'Unknown tool'}</div><div>${item.driver}</div><div>${item.authorization}</div><div>${JSON.parse(item.result_json||'{}').status||'Recorded'}</div></div>`).join(''):'<div class="stat-card">No execution activity recorded yet.</div>'}</div>`}
function environmentView(){return `${heading('REGISTRY / ENVIRONMENTS','Environment','Canonical hosts, services, addresses, and access references live here. They are retrieved only when relevant.','<button class="primary-button" data-action="add-environment">Add environment <span>+</span></button>')}<div id="environment-list" class="card"><div class="table-row table-head"><div>Name</div><div>Type</div><div>Address</div><div>Status</div></div></div>`}
function projectsView(){return `${heading('REGISTRY / PROJECTS','Projects','Projects organize chats and registered environments without changing execution permissions.','<button class="primary-button" data-action="add-project">Add project <span>+</span></button>')}<div id="project-list" class="grid grid-2"></div><div id="project-detail"></div>`}
function memoryView(){return `${heading('STATE / MEMORY','Memory','Durable memory is intentional, scoped, and provenance-aware. Scratch and telemetry are excluded.','<button class="primary-button" data-action="add-memory">Remember a fact <span>+</span></button>')}<div id="memory-list" class="card"></div>`}
function contextView(){return `${heading('DEBUG / CONTEXT','Context inspection','Inspect exactly what the broker selected, its token composition, and what it omitted.')}<div class="card form-panel"><div class="form-row"><div class="form-copy"><strong>Context build</strong><small>Preview uses a session-only secretary budget and does not call a model.</small></div><button class="primary-button" data-action="preview-context">Build preview <span>â</span></button></div><pre id="context-preview" class="execution-details" style="display:block;white-space:pre-wrap">No context build selected.</pre></div>`}
function discordView(){return heading('INTERFACE / DISCORD','Discord','Configure the bot through the secret store and inspect authoritative gateway state. Stored token values are never returned.')+'<section class="card form-panel"><div class="form-row"><div class="form-copy"><strong>Enabled</strong><small>Enable or disable the gateway without changing the stored secret.</small></div><label><input id="discord-enabled" type="checkbox"> Enable Discord</label></div><div class="form-row"><div class="form-copy"><strong>Bot token</strong><small>Enter only to add or replace it. The saved value is never sent back to this page.</small></div><input id="discord-token" type="password" class="select-control" autocomplete="new-password" placeholder="Only for adding/replacing"></div><div class="form-row"><div class="form-copy"><strong>Secret reference</strong><small>The reference is safe to display; the secret value is not.</small></div><input id="discord-secret-ref" class="select-control" value="discord-production" placeholder="discord-production"></div><div class="form-row"><div class="form-copy"><strong>Allowed guilds</strong><small>Comma-separated server IDs. Leave empty only when intentionally allowing all configured scope.</small></div><select id="discord-guild-select" class="select-control"><option value="">Discovering servers...</option></select><details class="advanced-details"><summary>Advanced: enter guild IDs</summary><input id="discord-guilds" class="select-control" placeholder="Guild IDs"></details></div><div class="form-row"><div class="form-copy"><strong>Allowed parent channels</strong><small>Conversation scope is evaluated against approved parent channels and persisted thread mappings.</small></div><select id="discord-channel-select" class="select-control"><option value="">Select a server first</option></select><details class="advanced-details"><summary>Advanced: enter channel IDs</summary><input id="discord-channels" class="select-control" placeholder="Channel IDs"></details></div><div class="form-row"><div class="form-copy"><strong>Allowed users</strong><small>Optional comma-separated user IDs.</small></div><input id="discord-users" class="select-control" placeholder="User IDs (optional)"></div><div class="form-row"><div class="form-copy"><strong>Message behavior</strong><small>Restrictive defaults protect DMs and mention handling.</small></div><label><input id="discord-dms" type="checkbox"> Allow DMs</label><label><input id="discord-mentions" type="checkbox"> Require bot mention</label></div><div class="form-row"><div class="form-copy"><strong>Operational alerts channel</strong><small>Alerts post directly here; conversation threads remain separate.</small></div><select id="discord-alert-select" class="select-control"><option value="">Select an alerts channel</option></select><details class="advanced-details"><summary>Advanced: enter alert channel ID</summary><input id="discord-alert-channel" class="select-control" placeholder="Channel ID (optional)"></details></div><div class="form-row"><div class="form-copy"><strong>Release notes channel</strong><small>Optional channel ID for release events.</small></div><input id="discord-release-channel" class="select-control" placeholder="Channel ID (optional)"></div><div id="discord-status" class="status-panel" role="status">Loading Discord status...</div><div style="display:flex;justify-content:flex-end;gap:10px;margin-top:20px"><button class="quiet-button" data-action="validate-discord">Refresh status</button><button class="primary-button" data-action="save-discord">Save Discord configuration</button></div></section>'}
const views={chat:chatView,dashboard:dashboardView,models:modelsView,providers:providersView,routing:routingView,settings:settingsView,roles:agentsView,workers:workersView,environment:environmentView,projects:projectsView,tools:toolsView,memory:memoryView,jobs:jobsView,integrations:discordView,activity:activityView,releases:()=>genericView('Releases / Updates','SYSTEM / RELEASES','Updates and rollback are coordinated by one Update Manager.'),context:contextView};
function showView(view){document.querySelector(".sidebar")?.classList.remove("mobile-open");document.querySelector(".mobile-nav-toggle")?.setAttribute("aria-expanded","false");currentView=view;renderNav();viewContent.innerHTML=(views[view]||views.dashboard)();viewTitle.textContent=({chat:'Chat',dashboard:'Dashboard',roles:'Agents / Roles',models:'Models',routing:'Routing',providers:'Providers',environment:'Environment',projects:'Projects',tools:'Tools',memory:'Memory',jobs:'Jobs',workers:'Workers',integrations:'Integrations',activity:'Activity',releases:'Releases / Updates',settings:'Settings'})[view]||'Workspace';viewKicker.textContent=view==='chat'?'Secretary':'Workspace';bindViewActions();if(view==='chat'){clearChatDemo();loadSessions().then(()=>{if(liveSessionId)loadSession(liveSessionId).catch(()=>newChat())}).catch(()=>{});}refreshLiveData(view);}
function clearChatDemo(){setSessionControls(null);const messages=document.querySelector('.chat-messages');if(messages)messages.innerHTML='<div class="stat-card" style="margin:auto;text-align:center;color:var(--muted)">Loading conversations...</div>';const details=document.querySelector('#execution-details');if(details)details.textContent='No execution details.';}
function bindViewActions(){const search=document.querySelector('#session-search');if(search&&!search.dataset.bound){search.dataset.bound='1';search.addEventListener('input',()=>loadSessions(search.value).catch(()=>{}));}viewContent.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>showView(el.dataset.view)));viewContent.querySelectorAll('[data-remove-route]').forEach(el=>el.addEventListener('click',()=>{routeChain.splice(Number(el.dataset.removeRoute),1);showView('routing')}));viewContent.querySelectorAll('.segment').forEach(el=>el.addEventListener('click',()=>{el.parentElement.querySelectorAll('.segment').forEach(x=>x.classList.remove('selected'));el.classList.add('selected')}));viewContent.querySelectorAll('[data-action]').forEach(bindAction);}
let liveSessionId=localStorage.getItem('virtizai.webui.session')||null;
let liveRouteId=null;
let sessionsCache=[];
let showArchived=false;
let webuiUserId=null;
async function resolveWebuiUser(){if(webuiUserId)return webuiUserId;const response=await fetch('/v1/interfaces/identity?interface_type=webui&external_subject=webui-user');if(!response.ok)throw new Error('WebUI identity unavailable');webuiUserId=(await response.json()).user_id;return webuiUserId;}
function sessionLabel(session){return session.title||'Untitled conversation'}
function formatSessionTime(value){if(!value)return '';const date=new Date(value.replace(' ','T')+'Z');return Number.isNaN(date.getTime())?value:date.toLocaleString([], {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});}
async function loadSessions(query=''){
  const params=new URLSearchParams({user_id:await resolveWebuiUser(),include_archived:String(showArchived)});if(query.trim())params.set('query',query.trim());
  const response=await fetch('/v1/sessions?'+params.toString());if(!response.ok)throw new Error('Could not load conversations');
  sessionsCache=await response.json();renderSessionList();
}
function renderSessionList(){const list=document.querySelector('#session-list');if(!list)return;const items=sessionsCache.filter(s=>showArchived?s.status==='archived':s.status!=='archived');if(!items.length){list.innerHTML=`<div class="stat-card">${showArchived?'No archived conversations.':'No conversations yet.'}</div>`;return;}list.innerHTML=items.map(session=>`<button class="session-item ${session.id===liveSessionId?'selected':''}" data-session-id="${session.id}"><strong>${sessionLabel(session)}</strong><small>${session.source||'WebUI'} · ${formatSessionTime(session.updated_at)}</small></button>`).join('');list.querySelectorAll('[data-session-id]').forEach(button=>button.addEventListener('click',()=>loadSession(button.dataset.sessionId)));}
function setSessionControls(session){const title=document.querySelector('#chat-session-title');const source=document.querySelector('#chat-session-source');if(title)title.textContent=session?sessionLabel(session):'New chat';if(source)source.textContent=session?`${session.source||'WebUI'} · ${session.status==='archived'?'Archived':'Saved conversation'}`:'WebUI · not saved until the first message';document.querySelectorAll('[data-action="rename-session"],[data-action="archive-session"]').forEach(button=>{button.disabled=!session;});}
function updateResponseMeta(metadata={},result={}){const pills=document.querySelectorAll('.response-meta .meta-pill');if(pills.length<6)return;const execution=metadata.execution_type||result.execution_type||'inference';const model=metadata.model_name||result.model_name||metadata.model_id||result.model_id||'None';const provider=metadata.provider_name||result.provider_name||metadata.provider_id||result.provider_id||'None';const tokens=metadata.total_tokens??result.total_tokens??'—';const latency=metadata.latency_ms??result.latency_ms;const locality=metadata.local??result.local;const fmt=latency==null?'—':`${Number(latency).toFixed(2)} ms`;pills[0].innerHTML=`<strong>Model</strong> ${model}`;pills[1].innerHTML=`<strong>Provider</strong> ${provider}`;pills[2].innerHTML=`<strong>Execution</strong> ${execution}`;pills[3].innerHTML=`<strong>Tokens</strong> ${tokens}`;pills[4].innerHTML=`<strong>Latency</strong> ${fmt}`;pills[5].innerHTML=`<strong>Local/cloud</strong> ${locality===true?'Local':locality===false?'Cloud':'—'}`;const details=document.querySelector('#execution-details');if(details)details.textContent=JSON.stringify(metadata||result,null,2);}
function renderPersistedMessage(message){const metadata=typeof message.metadata_json==='string'?(JSON.parse(message.metadata_json||'{}')||{}):(message.metadata_json||{});const role=message.role==='assistant'?'assistant':'user';appendChatMessage(role,message.content,`${role==='assistant'?'VirtizAI':'You'} · ${formatSessionTime(message.created_at)||'saved'}`,metadata);if(role==='assistant')updateResponseMeta(metadata);}
async function loadSession(sessionId){const response=await fetch(`/v1/sessions/${encodeURIComponent(sessionId)}?include_messages=true`);if(!response.ok)throw new Error('Conversation could not be loaded');const session=await response.json();liveSessionId=session.id;localStorage.setItem('virtizai.webui.session',liveSessionId);setSessionControls(session);const messages=document.querySelector('.chat-messages');if(messages){messages.innerHTML='';(session.messages||[]).forEach(renderPersistedMessage);if(!(session.messages||[]).length)messages.innerHTML='<div class="stat-card">No messages yet. Send the first message.</div>';}renderSessionList();}
function newChat(){liveSessionId=null;localStorage.removeItem('virtizai.webui.session');setSessionControls(null);const messages=document.querySelector('.chat-messages');if(messages)messages.innerHTML='<div class="stat-card" style="margin:auto;text-align:center;color:var(--muted)">No conversation yet. Start a new chat.</div>';renderSessionList();}
async function renameSession(){if(!liveSessionId)return;const session=sessionsCache.find(item=>item.id===liveSessionId);const title=window.prompt('Conversation name',sessionLabel(session||{}));if(!title||!title.trim())return;const response=await fetch(`/v1/sessions/${liveSessionId}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({title:title.trim()})});if(!response.ok)throw new Error('Conversation rename failed');const updated=await response.json();setSessionControls(updated);await loadSessions(document.querySelector('#session-search')?.value||'');}
async function archiveSession(){if(!liveSessionId)return;const response=await fetch(`/v1/sessions/${liveSessionId}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({archived:true})});if(!response.ok)throw new Error('Conversation archive failed');newChat();await loadSessions(document.querySelector('#session-search')?.value||'');}
async function sendLiveMessage(text){
  if(!liveSessionId){const created=await fetch('/v1/sessions',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({user_id:await resolveWebuiUser()})}).then(response=>{if(!response.ok)throw new Error('Could not create conversation');return response.json()});liveSessionId=created.session_id;localStorage.setItem('virtizai.webui.session',liveSessionId);}
  appendChatMessage('user',text,'You · just now');appendChatMessage('assistant','Working on it…','VirtizAI · waiting for provider');
  const result=await fetch('/v1/interfaces/message',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({interface_type:'webui',external_subject:'webui-user',content:text,session_id:liveSessionId})}).then(response=>{if(!response.ok)throw new Error(`Request failed (${response.status})`);return response.json()});
  liveSessionId=result.session_id;localStorage.setItem('virtizai.webui.session',liveSessionId);await loadSessions(document.querySelector('#session-search')?.value||'');await loadSession(liveSessionId);
  const metadata=result.metadata||{};updateResponseMeta(metadata,result);fetch('/v1/dashboard').then(response=>response.json()).then(updateInspector).catch(()=>{});
}
function appendChatMessage(role,content,meta,metadata={}){const messages=document.querySelector('.chat-messages');if(!messages)return;const empty=messages.querySelector('.stat-card');if(empty)empty.remove();const item=document.createElement('div');item.className=`message ${role==='user'?'user':''} ${role==='assistant'&&content==='Working on it…'?'pending':''}`;item.innerHTML=`<div class="message-avatar">${role==='user'?'U':'V'}</div><div><div class="message-bubble"></div><div class="message-meta"></div></div>`;item.querySelector('.message-bubble').textContent=content;item.querySelector('.message-meta').textContent=meta;if(role==='assistant'&&Object.keys(metadata||{}).length){const details=document.createElement('button');details.className='details-toggle';details.textContent='Details';details.type='button';details.addEventListener('click',()=>{const pre=document.createElement('pre');pre.className='execution-details';pre.textContent=JSON.stringify(metadata,null,2);pre.classList.toggle('open');details.replaceWith(pre)});item.lastElementChild.appendChild(details);}messages.appendChild(item);messages.scrollTop=messages.scrollHeight;}
async function saveProvider(){const status=document.querySelector('#provider-form-status');const name=document.querySelector('#provider-name').value.trim();const adapter_type=document.querySelector('#provider-type').value;const endpoint=document.querySelector('#provider-endpoint').value.trim();if(!name||!endpoint){status.textContent='Provider name and endpoint are required.';return}status.textContent='Saving provider and checking endpointâ¦';try{const created=await fetch('/v1/providers',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,adapter_type,endpoint})}).then(response=>{if(!response.ok)throw new Error('Provider could not be created');return response.json()});const health=await fetch(`/v1/providers/${created.id}/health`,{method:'POST'}).then(response=>response.json());if(health.state==='healthy')await fetch(`/v1/providers/${created.id}/discover`,{method:'POST'});showView('providers')}catch(error){status.textContent=error.message+' Check the endpoint and try again.'}}

async function loadSettings(){const status=document.querySelector('#settings-status');try{const identity=await fetch('/v1/interfaces/identity?interface_type=webui&external_subject=webui-user').then(r=>r.json());const prefs=await fetch('/v1/preferences/'+encodeURIComponent(identity.user_id)+'?interface_type=webui').then(r=>r.json());const values={response:prefs.response_verbosity,updates:prefs.execution_updates,tools:prefs.tool_details};Object.entries(values).forEach(([key,value])=>{document.querySelectorAll(`[data-setting="${key}"] .segment`).forEach(button=>button.classList.toggle('selected',button.dataset.value===value))});const routes=await fetch('/v1/routes').then(r=>r.json());const target=document.querySelector('#secretary-status');if(target){if(!routes.length){target.textContent='No Secretary route configured.'}else{const eligibility=await fetch('/v1/routes/'+routes[0].id+'/eligibility').then(r=>r.json());const first=(eligibility.routes||[])[0];target.textContent=first?`${first.provider_name}:${first.model_name} · ${first.status}${first.resident?' · warm':''}`:'Configured route has no eligible target.'}}}catch(error){if(status)status.textContent='Could not load settings from the backend.'}}
async function saveSettings(){const status=document.querySelector('#settings-status');const button=document.querySelector('[data-action="save-settings"]');if(button)button.disabled=true;try{const identity=await fetch('/v1/interfaces/identity?interface_type=webui&external_subject=webui-user').then(r=>r.json());const valueFor=key=>document.querySelector(`[data-setting="${key}"] .segment.selected`)?.dataset.value;const payload={user_id:identity.user_id,response_verbosity:valueFor('response')||'normal',execution_updates:valueFor('updates')||'important_milestones',tool_details:valueFor('tools')||'summary',interface_type:'webui'};const response=await fetch('/v1/preferences',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw new Error('Settings could not be saved.');status.textContent='Saved to the shared preference store.';await loadSettings()}catch(error){status.textContent=error.message}finally{if(button)button.disabled=false}}
function dataFormView(kind){const labels={project:['Add project','Project name','Description','Local path'],environment:['Add environment','Display name','Target type','Address'],memory:['Remember a fact','Memory text','Namespace','Source reference']};const [title,first,second,third]=labels[kind];return `${heading('STRUCTURED DATA',title,'Create canonical state without editing YAML or markdown.')}<section class="card form-panel"><div class="wizard-field"><label>${first}</label><input id="data-first" class="select-control" placeholder="${first}"></div><div class="wizard-field"><label>${second}</label><input id="data-second" class="select-control" placeholder="${second}"></div><div class="wizard-field"><label>${third}</label><input id="data-third" class="select-control" placeholder="${third}"></div><div id="data-form-status" class="subtext"></div><div style="display:flex;justify-content:flex-end;gap:10px;margin-top:22px"><button class="quiet-button" data-view="${kind==='project'?'projects':kind==='environment'?'environment':'memory'}">Cancel</button><button class="primary-button" data-action="save-${kind}">Save <span>â</span></button></div></section>`}
async function saveDiscord(){const status=document.querySelector('#discord-status');const button=document.querySelector('[data-action="save-discord"]');if(button)button.disabled=true;try{const ref=document.querySelector('#discord-secret-ref').value.trim()||'discord-production';const token=document.querySelector('#discord-token').value;if(token){const secret=await fetch('/v1/secrets/'+encodeURIComponent(ref),{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({value:token})});if(!secret.ok)throw new Error('Could not store the bot token securely.');document.querySelector('#discord-token').value=''}const guildSelect=document.querySelector('#discord-guild-select');const channelSelect=document.querySelector('#discord-channel-select');const alertSelect=document.querySelector('#discord-alert-select');if(guildSelect?.value)document.querySelector('#discord-guilds').value=guildSelect.value;if(channelSelect?.value)document.querySelector('#discord-channels').value=channelSelect.value;if(alertSelect?.value)document.querySelector('#discord-alert-channel').value=alertSelect.value;const csv=id=>(document.querySelector(id).value||'').split(',').map(value=>value.trim()).filter(Boolean);const payload={enabled:document.querySelector('#discord-enabled').checked,mode:'existing_bot',bot_secret_ref:ref,allow_dms:document.querySelector('#discord-dms').checked,require_mentions:document.querySelector('#discord-mentions').checked,slash_commands:true,dedicated_channel_id:null,release_channel_id:document.querySelector('#discord-release-channel').value.trim()||null,alert_channel_id:document.querySelector('#discord-alert-channel').value.trim()||null,allowed_servers:csv('#discord-guilds'),allowed_channels:csv('#discord-channels'),allowed_users:csv('#discord-users'),allowed_roles:[],admin_users:[],admin_roles:[]};const response=await fetch('/v1/discord/config',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw new Error('Could not save Discord configuration.');status.textContent='Saved. Gateway status is shown without exposing the token.';await loadDiscordConfig()}catch(error){status.textContent=error.message}finally{if(button)button.disabled=false}}
async function createRoute(){
  const status=document.querySelector('#route-status');
  try{
    const [roles,models]=await Promise.all([fetch('/v1/roles').then(r=>r.json()),fetch('/v1/models').then(r=>r.json())]);
    if(!roles.length||!models.length){showView('routing');return;}
    const response=await fetch('/v1/routes',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'Secretary',role_id:roles[0].id,strategy:'priority',priority:10,targets:[{provider_id:models[0].provider_id,model_id:models[0].id,ordinal:0}]})});
    if(!response.ok)throw new Error('Could not create route');
    showView('routing');
  }catch(error){if(status)status.textContent=error.message}
}
async function saveRoute(){const status=document.querySelector('#route-status');if(!liveRouteId){if(status)status.textContent='No persisted Secretary route is available yet.';return}const targets=[...document.querySelectorAll('[data-route-provider]')].map((providerSelect,index)=>({provider_id:providerSelect.value,model_id:document.querySelector(`[data-route-model="${index}"]`).value,ordinal:index}));const response=await fetch(`/v1/routes/${liveRouteId}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({strategy:document.querySelector('#route-strategy').value,targets})});if(status)status.textContent=response.ok?'Saved. Secretary will use the new eligible order on the next request.':'Could not save route changes.';if(response.ok)showView('routing')}
async function saveStructured(kind){const first=document.querySelector('#data-first').value.trim();const second=document.querySelector('#data-second').value.trim();const third=document.querySelector('#data-third').value.trim();const status=document.querySelector('#data-form-status');if(!first){status.textContent='A name or content value is required.';return}let endpoint,payload,next;if(kind==='project'){endpoint='/v1/projects';payload={name:first,description:second||null,root_path:third||null};next='projects'}else if(kind==='environment'){endpoint='/v1/environments';payload={name:first,target_type:second||'local',address:third||null};next='environment'}else{endpoint='/v1/memory';payload={content:first,namespace:second||'global',source_ref:third||null,user_id:'webui-user'};next='memory'}const response=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});if(!response.ok){status.textContent='Could not save this record.';return}showView(next)}
async function previewContext(){const session=await fetch('/v1/sessions',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({user_id:'webui-user'})}).then(response=>response.json());const result=await fetch(`/v1/context?user_id=webui-user&session_id=${session.session_id}&sources=conversation,memory,project,environment`).then(response=>response.json());document.querySelector('#context-preview').textContent=JSON.stringify(result,null,2)}
function bindAction(el){el.addEventListener('click',()=>{const action=el.dataset.action;if(action==='toggle-nav'){const sidebar=document.querySelector(".sidebar");const open=sidebar?.classList.toggle("mobile-open");el.setAttribute("aria-expanded",open?'true':'false');return;}if(action==='close-wizard'){closeWizard();return}if(action==='wizard-back'||action==='wizard-next'){wizardAction(action);return}if(action==='new-chat'){newChat();return}if(action==='toggle-archived'){showArchived=!showArchived;loadSessions().catch(()=>{});return}if(action==='rename-session'){renameSession().catch(error=>console.debug(error));return}if(action==='archive-session'){archiveSession().catch(error=>console.debug(error));return}if(action==='open-wizard')openWizard();if(action==='open-settings')showView('settings');if(action==='toggle-details')document.querySelector('#execution-details')?.classList.toggle('open');if(action==='save-provider'){saveProvider();return}if(action==='save-discord'){saveDiscord();return}if(action==='save-settings'){saveSettings();return}if(action==='validate-discord'){validateDiscord();return}if(action==='save-route'){saveRoute();return}if(action==='preview-context'){previewContext();return}if(action==='save-project'||action==='save-environment'||action==='save-memory'){saveStructured(action.replace('save-',''));return}if(action==='send-message'){const textarea=document.querySelector('.composer textarea');if(textarea.value.trim()){const text=textarea.value.trim();textarea.value='';sendLiveMessage(text).catch(error=>{const pending=document.querySelector('.message.pending');if(pending){pending.classList.remove('pending');pending.querySelector('.message-bubble').textContent=`Unable to get a response: ${error.message}`;pending.querySelector('.message-meta').textContent='VirtizAI Â· request failed';}});el.animate([{transform:'scale(1)'},{transform:'scale(.9)'},{transform:'scale(1)'}],{duration:220})}}if(action==='add-route'){createRoute();return}if(action==='add-provider'){viewContent.innerHTML=providerFormView();bindViewActions();}if(action==='add-project'||action==='add-environment'||action==='add-memory'){viewContent.innerHTML=dataFormView(action.replace('add-',''));bindViewActions();}if(action==='discover-models')showView('models');if(action==='placeholder-action')showView('settings')})}
function openWizard(){wizard.classList.remove('hidden');wizard.setAttribute('aria-hidden','false');wizardStep=0;renderWizard();}
function closeWizard(){wizard.classList.add('hidden');wizard.setAttribute('aria-hidden','true');}
