async function loadWizardRoute(){if(wizardStep!==2)return;const providerSelect=document.querySelector('[aria-label="Secretary provider"]');const modelSelect=document.querySelector('[aria-label="Secretary model"]');if(!providerSelect||!modelSelect)return;try{const [providers,models]=await Promise.all([fetch('/v1/providers').then(r=>r.json()),fetch('/v1/models').then(r=>r.json())]);providerSelect.innerHTML=providers.length?providers.map(p=>`<option value="${p.id}">${p.name}</option>`).join(''):'<option value="">No provider selected</option>';modelSelect.innerHTML=models.length?models.map(m=>`<option value="${m.id}" data-provider="${m.provider_id}">${m.name} · ${m.provider_name||''}</option>`).join(''):'<option value="">No model selected</option>';const filter=()=>{const pid=providerSelect.value;[...modelSelect.options].forEach(o=>{o.hidden=!!pid&&o.dataset.provider!==pid});const first=[...modelSelect.options].find(o=>!o.hidden);if(first)modelSelect.value=first.value};providerSelect.addEventListener('change',filter);filter()}catch(error){providerSelect.innerHTML='<option value="">Provider discovery unavailable</option>';modelSelect.innerHTML='<option value="">Model discovery unavailable</option>'}}
function renderWizard(){document.querySelector('#wizard-count').textContent=`Step ${wizardStep+1} of ${wizardNames.length}`;document.querySelector('#wizard-steps').innerHTML=wizardNames.map((name,i)=>`<div class="wizard-step ${i===wizardStep?'current':''} ${i<wizardStep?'done':''}"><span>${i<wizardStep?'✓':i+1}</span>${name}</div>`).join('');const [title,lede,body]=wizardBodies[wizardStep];document.querySelector('#wizard-content').innerHTML=`<span class="eyebrow">${wizardNames[wizardStep].toUpperCase()}</span><h2>${title}</h2><p class="lede">${lede}</p>${body}`;document.querySelector('[data-action="wizard-back"]').style.visibility=wizardStep===0?'hidden':'visible';document.querySelector('[data-action="wizard-next"]').innerHTML=wizardStep===wizardNames.length-1?'Finish <span>✓</span>':'Continue <span>→</span>';loadWizardRoute().catch(()=>{});}
async function wizardAction(action){if(action==='wizard-back'&&wizardStep>0){wizardStep--;renderWizard()}if(action==='wizard-next'){if(wizardStep===5){const name=document.querySelector('[aria-label="Wizard provider name"]')?.value.trim();const endpoint=document.querySelector('[aria-label="Wizard provider endpoint"]')?.value.trim();if(name&&endpoint){const created=await fetch('/v1/providers',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,adapter_type:'ollama',endpoint})}).then(r=>r.ok?r.json():null);if(created){await fetch('/v1/providers/'+created.id+'/health',{method:'POST'});await fetch('/v1/providers/'+created.id+'/discover',{method:'POST'})}}}if(wizardStep===2){const provider=document.querySelector('[aria-label="Secretary provider"]')?.value;const model=document.querySelector('[aria-label="Secretary model"]')?.value;if(provider&&model){const [roles,routes]=await Promise.all([fetch('/v1/roles').then(r=>r.json()),fetch('/v1/routes').then(r=>r.json())]);if(!routes.length&&roles.length)await fetch('/v1/routes',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:'Secretary',role_id:roles.find(r=>r.name==='secretary')?.id||roles[0].id,strategy:'priority',priority:10,targets:[{provider_id:provider,model_id:model,ordinal:0}]})})}}if(wizardStep<wizardNames.length-1){wizardStep++;renderWizard()}else{const state=await fetch('/v1/readiness').then(r=>r.json()).catch(()=>null);if(state?.setup_complete){closeWizard()}else{document.querySelector('#wizard-content').insertAdjacentHTML('beforeend','<div class="wizard-note">Setup is not complete yet. Add a provider, discover a model, and choose a Secretary route before finishing. Discord remains optional.</div>')}}}}
async function loadReleasesView(){
  const data=await fetch('/v1/releases').then(response=>response.json());
  const releases=data.releases||[];
  viewContent.innerHTML=`${heading('SYSTEM / RELEASES','Releases / Updates','Release metadata, policy, and history are shared by WebUI, Discord, and CLI. Privileged installs run outside the application.')}<section class="card"><div class="panel-heading"><h3>Update policy</h3><button id="check-updates" class="primary-button">Check updates <span>â¥</span></button></div><p class="subtext">Channel: ${data.policy.channel} Â· Policy: ${data.policy.version_policy}${data.policy.pinned_version?` Â· Pinned: ${data.policy.pinned_version}`:''}</p><div id="release-plan" class="wizard-note">No update check has run.</div></section><section class="card" style="margin-top:16px"><div class="panel-heading"><h3>Known releases</h3></div>${releases.length?releases.map(item=>`<div class="table-row"><div>${item.version}</div><div>${item.channel}</div><div>${item.release_url}</div></div>`).join(''):'<p class="subtext">No release manifests imported yet.</p>'}</section>`;
  document.querySelector('#check-updates').addEventListener('click',async()=>{const plan=await fetch('/v1/updates/plan?platform=debian-amd64').then(response=>response.json());document.querySelector('#release-plan').textContent=plan.available?`Verified update available: ${plan.release.version}. Apply it with the platform updater helper or your external deployment tool.`:'No verified update is available for this platform and policy.'});
}
async function loadReadiness(){try{const state=await fetch('/v1/readiness').then(r=>r.json());if(!state.setup_complete&&new URLSearchParams(location.search).get('wizard')!=='0')openWizard();}catch(error){console.debug('readiness unavailable',error)}}
const baseShowView=showView;
async function loadDiscordDiscovery(){
  const guildSelect=document.querySelector('#discord-guild-select');
  const channelSelect=document.querySelector('#discord-channel-select');
  const alertSelect=document.querySelector('#discord-alert-select');
  if(!guildSelect)return;
  try{
    const result=await fetch('/v1/discord/discovery').then(r=>r.json());
    guildSelect.innerHTML='';
    if(!result.ok){guildSelect.innerHTML=`<option value="">${result.message||'Discovery unavailable'}</option>`;return;}
    const guilds=result.guilds||[];
    guilds.forEach(g=>{const option=document.createElement('option');option.value=g.id;option.textContent=`${g.name} (${g.id})`;guildSelect.appendChild(option)});
    if(!guilds.length)guildSelect.innerHTML='<option value="">No accessible servers</option>';
    const fillChannels=()=>{const guild=guilds.find(item=>item.id===guildSelect.value);const channels=guild?.channels||[];channelSelect.innerHTML=channels.length?'':'<option value="">No accessible channels</option>';channels.forEach(c=>{const option=document.createElement('option');option.value=c.id;option.textContent=`${c.name} (${c.id})`;channelSelect.appendChild(option)});if(alertSelect){alertSelect.innerHTML='<option value="">No alerts channel selected</option>';channels.filter(c=>c.alert_candidate).forEach(c=>{const option=document.createElement('option');option.value=c.id;option.textContent=`${c.name} (${c.id})`;alertSelect.appendChild(option)})}};
    guildSelect.addEventListener('change',fillChannels,{once:false});
    if(window.discordConfiguredGuild)guildSelect.value=window.discordConfiguredGuild;
    fillChannels();
    if(window.discordConfiguredChannel)channelSelect.value=window.discordConfiguredChannel;
    if(window.discordConfiguredAlert&&alertSelect)alertSelect.value=window.discordConfiguredAlert;
  }catch(error){guildSelect.innerHTML='<option value="">Discovery request failed</option>'}
}
async function validateDiscord(){const status=document.querySelector('#discord-status');if(status)status.textContent='Validating gateway, scope, and permissions...';try{const result=await fetch('/v1/discord/validate').then(r=>r.json());if(status)status.textContent=result.ok?'Validation passed: gateway and configured Discord scope are accessible.':`Validation incomplete: ${result.message||'check the configured guild/channel scope.'}`;}catch(error){if(status)status.textContent='Validation request failed.'}}
async function loadDiscordConfig(){try{const d=await fetch('/v1/discord/config').then(r=>r.json());const set=(id,v)=>{const e=document.querySelector(id);if(e&&v!==undefined)e.value=v||''};const csv=v=>(v||[]).join(', ');window.discordConfiguredGuild=(d.allowed_servers||[])[0]||'';window.discordConfiguredChannel=(d.allowed_channels||[])[0]||'';window.discordConfiguredAlert=d.alert_channel_id||'';const enabled=document.querySelector('#discord-enabled');if(enabled)enabled.checked=!!d.enabled;const dms=document.querySelector('#discord-dms');if(dms)dms.checked=!!d.allow_dms;const mentions=document.querySelector('#discord-mentions');if(mentions)mentions.checked=!!d.require_mentions;set('#discord-secret-ref',d.bot_secret_ref||'discord-production');set('#discord-guilds',csv(d.allowed_servers));set('#discord-channels',csv(d.allowed_channels));set('#discord-users',csv(d.allowed_users));set('#discord-release-channel',d.release_channel_id);set('#discord-alert-channel',d.alert_channel_id);const st=document.querySelector('#discord-status');if(st){const gateway=d.gateway||{};st.textContent=`Gateway: ${gateway.status||'disabled'} · Bot token: ${d.bot_secret_configured?'Configured':'Not configured'} · Guild scope: ${d.allowed_servers?.length?'Configured':'Not configured'} · Conversation scope: ${d.allowed_channels?.length?'Configured':'Not configured'}${gateway.last_error?' · Last error: '+gateway.last_error:''}`}}catch(e){const st=document.querySelector('#discord-status');if(st)st.textContent='Unable to read Discord status.'}loadDiscordDiscovery()}
showView=function(view){baseShowView(view);if(view==='integrations')loadDiscordConfig();if(view==='settings')loadSettings();if(view==='releases')loadReleasesView().catch(()=>{viewContent.innerHTML=genericView('Releases / Updates','SYSTEM / RELEASES','Release metadata is unavailable.');});};
document.querySelectorAll('[data-action]').forEach(bindAction);
renderNav();showView('chat');loadReadiness();
if(new URLSearchParams(location.search).get('wizard')==='1')openWizard();
fetch('/healthz').then(response=>response.ok?response.json():null).then(health=>{
  if(!health)return;
  document.querySelectorAll('.build-tag').forEach(el=>el.textContent=`VirtizAI ${health.version}`);
  document.querySelectorAll('.wizard-foot').forEach(el=>el.innerHTML=`<span class="status-dot healthy"></span> Core ready Â· schema v${health.schema_version}`);
}).catch(()=>{});

async function refreshLiveData(view){
  if(view==='dashboard'){
    try{const data=await fetch('/v1/dashboard').then(response=>response.json());viewContent.innerHTML=liveDashboardView(data);bindViewActions();updateInspector(data);}catch(error){console.debug('Dashboard data unavailable',error)}
    return;
  }
  if(!['chat','providers','models','routing','tools','jobs','workers','roles','activity','environment','projects','memory'].includes(view))return;
  try{
    const [providerResponse,modelResponse]=await Promise.all([fetch('/v1/providers'),fetch('/v1/models')]);
    const providers=await providerResponse.json();
    const models=await modelResponse.json();
    if(view==='providers' && providers.length){
      const rows=providers.map(provider=>`<div class="table-row"><div class="service-name"><span class="status-dot ${provider.health_status}"></span><div>${provider.name}<small>${provider.adapter_type} Â· ${provider.endpoint||'isolated/local'}</small></div></div><div>${models.filter(model=>model.provider_id===provider.id).length} models</div><div>${statusBadge(provider.health_status)}</div><div><button class="text-link" data-provider-health="${provider.id}">Check â</button></div></div>`).join('');
      const panel=viewContent.querySelector('.card'); if(panel)panel.innerHTML=rows;
    }
    if(view==='models' && models.length){
      const html=models.map(model=>`<div class="card stat-card"><div class="service-name"><span class="route-icon coral">M</span><div>${model.name}<small>${model.provider_name} Â· ${model.locality||'capability metadata pending'}</small></div><span style="margin-left:auto">${statusBadge(model.status)}</span></div><div class="subtext" style="margin-top:16px">${model.context_window?`Context ${model.context_window}`:'Context unknown'} Â· discovered live</div></div>`).join('');
      const grid=viewContent.querySelector('.grid'); if(grid)grid.innerHTML=html;
    }
    if(view==='routing'){
      const panel=viewContent.querySelector('#route-panel');
      const routes=await fetch('/v1/routes').then(response=>response.json());
      if(panel&&!routes.length){liveRouteId=null;panel.innerHTML='<div class="panel-heading"><h3>No routes configured</h3><button class="primary-button" data-action="add-route">Create route</button></div><p class="subtext">Discover a provider model first, then create a real role route.</p>';bindViewActions();return;}
      if(panel&&routes.length){
        liveRouteId=routes[0].id;
        const eligibility=await fetch('/v1/routes/'+routes[0].id+'/eligibility').then(response=>response.json());
        const opts=models.map(model=>'<option data-provider="'+model.provider_id+'" value="'+model.id+'">'+model.provider_name+' / '+model.name+' ['+model.status+']</option>').join('');
        panel.innerHTML='<div class="panel-heading"><div><h3>'+routes[0].name+'</h3><span class="subtext">'+(routes[0].role_name||'role')+'</span></div><button class="primary-button" data-action="save-route">Save route</button></div><label>Strategy<select id="route-strategy" class="select-control"><option value="priority">Priority</option><option value="lowest_latency">Lowest latency</option><option value="balanced">Balanced</option></select></label><label>Provider:model targets<select id="route-target-select" class="select-control" multiple size="8">'+opts+'</select></label><div id="route-status" class="subtext">'+((eligibility.warnings||[])[0]||'Eligibility loaded')+'</div>';
        const sel=panel.querySelector('#route-target-select');(eligibility.routes||[]).forEach(target=>{const o=[...sel.options].find(x=>x.value===target.model_id);if(o)o.selected=true});
        bindViewActions();
      }
    }
    if(view==='chat'){
      const routes=await fetch('/v1/routes').then(response=>response.json());
      const side=viewContent.querySelector('.chat-side .side-card');
      if(side&&routes.length){const eligibility=await fetch(`/v1/routes/${routes[0].id}/eligibility`).then(response=>response.json());side.innerHTML=`<span class="eyebrow">ACTIVE ROUTE</span><h3 style="margin-top:7px">${routes[0].name}</h3>${eligibility.routes.slice(0,3).map((route,index)=>`<div class="route-card"><span class="route-icon ${index?'blue':'coral'}">${index+1}</span><span><strong>${route.provider_name}</strong><small>${route.model_name} Â· ${statusBadge('healthy')}</small></span></div>`).join('')}<button class="text-link" data-view="routing">Edit route chain â</button>`;side.querySelector('[data-view]')?.addEventListener('click',()=>showView('routing'));}
    }
    if(view==='tools'){
      const tools=await fetch('/v1/tools').then(response=>response.json());
      const list=viewContent.querySelector('#tools-list'); if(list)list.innerHTML=tools.map(tool=>`<div class="card stat-card"><div class="service-name"><span class="route-icon coral">â</span><div>${tool.display_name}<small>${tool.name} Â· ${tool.description}</small></div></div><div class="subtext" style="margin-top:14px">Permissions: ${tool.required_permissions.join(', ')} Â· Drivers: ${tool.allowed_drivers.join(', ')}</div><button class="text-link" data-tool-run="${tool.name}" style="margin-top:12px">Run safe demo â</button></div>`).join('');
    }
    if(view==='roles'){
      const agents=await fetch('/v1/agents').then(response=>response.json());
      const list=viewContent.querySelector('#agents-list'); if(list)list.innerHTML=agents.map(agent=>`<div class="card stat-card"><div class="service-name"><span class="route-icon coral">A</span><div><strong>${agent.name}</strong><small>${agent.purpose||'Agent role'} · ${agent.enabled===false?'disabled':'enabled'}</small></div></div><div class="subtext">Route: ${agent.route?agent.route.name:'not configured'} · Model selection remains in Routing.</div><div class="subtext">Tools: ${(agent.tools||[]).map(tool=>tool.display_name||tool.name).join(', ')||'none registered'}</div></div>`).join('')||'<div class="card stat-card">No agents registered.</div>';
    }
    if(view==='workers'){
      const workers=await fetch('/v1/workers').then(response=>response.json());
      const list=viewContent.querySelector('#workers-list'); if(list)list.innerHTML=workers.map(worker=>`<div class="card stat-card"><div class="service-name"><span class="route-icon blue">W</span><div><strong>${worker.name}</strong><small>${worker.kind} · ${worker.available?'available':'unavailable'}</small></div>${statusBadge(worker.available?'healthy':'unavailable')}</div><div class="subtext">Active jobs: ${worker.active_jobs} · Authentication: ${worker.authenticated===null?'managed by worker runtime':worker.authenticated?'authenticated':'pending'}</div><div class="subtext">Workspace restricted to configured worker root.</div></div>`).join('')||'<div class="card stat-card">No workers registered.</div>';
    }
    if(view==='jobs'){
      const jobs=await fetch('/v1/jobs').then(response=>response.json());
      const list=viewContent.querySelector('#jobs-list'); if(list)list.innerHTML='<div class="table-row table-head"><div>Job</div><div>Status</div><div>Worker</div><div>Actions</div></div>'+jobs.map(job=>`<div class="table-row"><div class="service-name">${job.id}<small>${job.created_at||''} · session ${job.session_id||'none'}</small></div><div>${job.status}</div><div>${job.kind}</div><div>${['queued','running'].includes(job.status)?`<button class="text-link" data-cancel-job="${job.id}">Cancel</button>`:'<button class="text-link" data-job-details="'+job.id+'">Details</button>'}</div></div>`).join('');
    }
    if(view==='activity'){
      const events=await fetch('/v1/activity').then(response=>response.json());
      const list=viewContent.querySelector('#activity-list'); if(list)list.innerHTML='<div class="table-row table-head"><div>Tool</div><div>Driver</div><div>Authorization</div><div>Result</div></div>'+events.map(event=>`<div class="table-row"><div>${event.tool_id||'unknown'}</div><div>${event.driver}</div><div>${event.authorization}</div><div>${JSON.parse(event.result_json||'{}').status||'recorded'}</div></div>`).join('');
    }
    if(view==='environment'){
      const items=await fetch('/v1/environments').then(response=>response.json());
      const list=viewContent.querySelector('#environment-list'); if(list)list.innerHTML='<div class="table-row table-head"><div>Name</div><div>Type</div><div>Address</div><div>Status</div></div>'+items.map(item=>`<div class="table-row"><div class="service-name">${item.name}<small>${item.tags||'canonical target'}</small></div><div>${item.target_type}</div><div>${item.address||'local'}</div><div>${statusBadge(item.health_status)}</div></div>`).join('');
    }
    if(view==='projects'){
      const items=await fetch('/v1/projects').then(response=>response.json());
      const list=viewContent.querySelector('#project-list'); if(list)list.innerHTML=items.map(item=>`<div class="card stat-card"><div class="service-name"><div><h3>${item.name}</h3><small>${item.status||'active'} · ${item.session_count||0} chats</small></div><button class="text-link" data-open-project="${item.id}">Open →</button></div><p class="subtext">${item.objective||item.description||'No objective recorded'}</p></div>`).join('')||'<div class="card stat-card">No projects registered.</div>';
    }
    if(view==='memory'){
      const items=await fetch('/v1/memory').then(response=>response.json());
      const list=viewContent.querySelector('#memory-list'); if(list)list.innerHTML=items.map(item=>`<div class="table-row"><div>${item.namespace}</div><div>${item.content}</div><div>${item.source_ref||'manual'}</div><div>${item.verified_state||'unverified'}</div></div>`).join('')||'<div class="stat-card">No durable memory registered.</div>';
    }
    viewContent.querySelectorAll('[data-open-project]').forEach(button=>button.addEventListener('click',async()=>{const project=await fetch(`/v1/projects/${button.dataset.openProject}`).then(r=>r.json());const detail=viewContent.querySelector('#project-detail');if(detail)detail.innerHTML=`<section class="card"><div class="panel-heading"><div><h3>${project.name}</h3><span class="subtext">${project.status||'active'} · ${project.objective||project.description||'No objective'}</span></div><button class="quiet-button" data-view="chat">Open chat</button></div><p class="subtext">Chats: ${project.sessions.length} · Environments: ${project.environments.length} · Jobs: ${project.jobs.length}</p><div class="subtext">${project.sessions.map(item=>item.title||item.id).join(', ')||'No associated chats'}</div></section>`;detail.querySelector('[data-view]')?.addEventListener('click',()=>showView('chat'));}));
    viewContent.querySelectorAll('[data-cancel-job]').forEach(button=>button.addEventListener('click',async()=>{await fetch(`/v1/jobs/${button.dataset.cancelJob}/cancel`,{method:'POST'});showView('jobs')}));viewContent.querySelectorAll('[data-job-details]').forEach(button=>button.addEventListener('click',async()=>{const job=await fetch(`/v1/jobs/${button.dataset.jobDetails}`).then(r=>r.json());alert(JSON.stringify(job,null,2))}));viewContent.querySelectorAll('[data-provider-health]').forEach(button=>button.addEventListener('click',async()=>{await fetch(`/v1/providers/${button.dataset.providerHealth}/health`,{method:'POST'});showView('providers')}));
    viewContent.querySelectorAll('[data-tool-run]').forEach(button=>button.addEventListener('click',async()=>{button.textContent='Runningâ¦';await fetch('/v1/tools/run',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({tool:button.dataset.toolRun,profile:'general'})});button.textContent='Queued Â· refresh Jobs â'}));
  }catch(error){console.debug('Live registry refresh unavailable',error)}
}
function updateInspector(data){const blocks=document.querySelectorAll('.inspector .metric-block');const latency=data.secretary_latency_ms==null?'No data':`${Number(data.secretary_latency_ms).toFixed(2)} ms`;const jobs=Object.values(data.jobs||{}).reduce((sum,value)=>sum+value,0);if(blocks[0]){blocks[0].querySelector('strong').textContent=latency;blocks[0].querySelector('small').textContent=`${data.secretary_response_count||0} measured responses`;}if(blocks[1]){blocks[1].querySelector('.metric-label').textContent='Jobs recorded';blocks[1].querySelector('strong').textContent=String(jobs).padStart(2,'0');blocks[1].querySelector('small').textContent=`${data.jobs?.running||0} running Â· ${data.jobs?.queued||0} queued`;blocks[1].style.cursor='pointer';blocks[1].title='Open Jobs';blocks[1].onclick=()=>showView('jobs');}const recent=document.querySelector('.inspector .recent');if(recent){const activity=data.recent_activity||[];recent.innerHTML='<div class="section-label">Recent activity</div>'+(activity.length?activity.slice(0,2).map(item=>`<div class="activity-line"><div><strong>${item.tool_id||'Execution event'}</strong><small>${item.driver} Â· ${JSON.parse(item.result_json||'{}').status||'recorded'}</small></div></div>`).join(''):'<div class="activity-line"><div><strong>No activity yet</strong><small>Live execution events appear here</small></div></div>');}}
